tests_caches.test_game_state_invente.gd:
extends GdUnitTestSuite
## Test caché de la proposition fictive : GameState.add_coins.

const GameStateScript := preload("res://scripts/game_state.gd")


func test_ajoute_les_pieces() -> void:
	var etat: Node = auto_free(GameStateScript.new())
	etat.add_coins(3)
	etat.add_coins(2)
	assert_int(etat.coins).is_equal(5)


func test_ignore_les_montants_nuls_ou_negatifs() -> void:
	var etat: Node = auto_free(GameStateScript.new())
	etat.add_coins(0)
	etat.add_coins(-4)
	assert_int(etat.coins).is_equal(0)


func test_signale_le_nouveau_total() -> void:
	var etat: Node = auto_free(GameStateScript.new())
	var totaux: Array = []
	etat.coins_changed.connect(func(total: int) -> void: totaux.append(total))
	etat.add_coins(4)
	assert_array(totaux).is_equal([4])
